/**
 * Unit tests for DeserializationConfig#initialize
 */
public class DeserializationConfig_initialize_TriageGen0Test {

    private BaseSettings baseSettings;
    private SubtypeResolver subtypeResolver;
    private SimpleMixInResolver mixins;
    private RootNameLookup rootNames;
    private JsonParser mockParser;

    @Before
    public void setUp() {
        baseSettings = mock(BaseSettings.class);
        subtypeResolver = mock(SubtypeResolver.class);
        mixins = mock(SimpleMixInResolver.class);
        rootNames = mock(RootNameLookup.class);
        mockParser = mock(JsonParser.class);
    }

    /**
     * Test case where no features are to be changed.
     * Covers the case where both _parserFeaturesToChange and _formatReadFeaturesToChange are 0.
     */
    @Test
    public void testInitialize_NoFeaturesToChange() {
        // Using a subclass or a way to instantiate DeserializationConfig with 0 features.
        // Since the fields are likely private, we rely on the default state of a new config.
        DeserializationConfig config = new StdDeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames);

        config.initialize(mockParser);

        verify(mockParser, never()).overrideStdFeatures(anyInt(), anyInt());
        verify(mockParser, never()).overrideFormatFeatures(anyInt(), anyInt());
    }

    /**
     * Test case where only parser features are to be changed.
     */
    @Test
    public void testInitialize_OnlyParserFeaturesToChange() {
        // We use the 'with' methods to trigger the setting of features.
        // However, the 'initialize' method specifically looks at '_parserFeaturesToChange'.
        // In Jackson, these 'toChange' masks are typically set during the 'with' or 'without' operations 
        // on the internal state which are then applied during initialize.

        // Since we cannot easily access the protected 'toChange' fields directly without reflection,
        // we simulate the behavior by creating a config that has undergone modifications.

        // Note: In actual Jackson implementation, 'with' methods return a new config with the feature set 
        // and the 'toChange' mask populated.

        DeserializationConfig config = new StdDeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames)
                .with(JsonParser.Feature.AUTO_CLOSE_SOURCE);

        // We need to ensure the internal _parserFeaturesToChange is non-zero.
        // If the 'with' method doesn't trigger the 'toChange' logic in this specific version/setup,
        // we would use reflection.

        try {
            setPrivateField(config, "_parserFeaturesToChange", JsonParser.Feature.AUTO_CLOSE_SOURCE.hashCode());
            setPrivateField(config, "_parserFeatures", JsonParser.Feature.AUTO_CLOSE_SOURCE.hashCode());
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        config.initialize(mockParser);

        verify(mockParser, times(1)).overrideStdFeatures(eq(JsonParser.Feature.AUTO_CLOSE_SOURCE.hashCode()), eq(JsonParser.Feature.AUTO_CLOSE_SOURCE.hashCode()));
        verify(mockParser, never()).overrideFormatFeatures(anyInt(), anyInt());
    }

    /**
     * Test case where only format features are to be changed.
     */
    @Test
    public void testInitialize_OnlyFormatFeaturesToChange() {
        DeserializationConfig config = new StdDeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames)
                .with(JsonParser.Feature.AUTO_CLOSE_SOURCE);

        try {
            setPrivateField(config, "_formatReadFeaturesToChange", 1); // non-zero
            setPrivateField(config, "_formatReadFeatures", 1);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        config.initialize(mockParser);

        verify(mockParser, never()).overrideStdFeatures(anyInt(), anyInt());
        verify(mockParser, times(1)).overrideFormatFeatures(eq(1), eq(1));
    }

    /**
     * Test case where both parser and format features are to be changed.
     */
    @Test
    public void testInitialize_BothFeaturesToChange() {
        DeserializationConfig config = new StdDeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames);

        try {
            setPrivateField(config, "_parserFeaturesToChange", 1);
            setPrivateField(config, "_parserFeatures", 1);
            setPrivateField(config, "_formatReadFeaturesToChange", 2);
            setPrivateField(config, "_formatReadFeatures", 2);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        config.initialize(mockParser);

        verify(mockParser, times(1)).overrideStdFeatures(1, 1);
        verify(mockParser, times(1)).overrideFormatFeatures(2, 2);
    }

    /**
     * Helper to set private fields for testing purposes since the logic depends on internal state.
     */
    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }
}

/**
 * Dummy class to allow instantiation of DeserializationConfig if it's abstract or has restricted access.
 * In Jackson, StdDeserializationConfig is the standard implementation.
 */
class StdDeserializationConfig extends DeserializationConfig {
    public StdDeserializationConfig(BaseSettings base, SubtypeResolver str, SimpleMixInResolver mixins, RootNameLookup rootNames) {
        super(base, str, mixins, rootNames);
    }
}
